/**
 * SS3 WS-1, WS-2: Node seals and opens workspace objects exactly as the
 * worker's `SealedObjectStore` does, so a fork's copies are readable by the
 * fork's worker. The vector is generated by Python and tested on both sides.
 */
import { expect } from 'chai';
import { readFileSync } from 'fs';
import path from 'path';
import {
  decodeSealedId,
  encodeSealedId,
  ObjectUnreadableError,
  openObject,
  sealObject,
  SealingKey,
  SealingScope,
} from '../../../src/modules/agent-harness/domain/workspace-sealing';
import { InMemoryWorkspaceObjects } from '../../../src/modules/agent-harness/adapters/in-memory-workspace-objects';

interface VectorCase {
  name: string;
  tenantId: string;
  partition: string;
  keyId: string;
  key: string;
  plaintext: string;
  contentHash: string;
  sizeBytes: number;
  objectId: string;
  stored: string;
}

const VECTORS = (
  JSON.parse(
    readFileSync(
      path.resolve(__dirname, '../../../../../../contracts/harness/vectors/workspace-sealing.json'),
      'utf8',
    ),
  ) as { objects: VectorCase[] }
).objects;

const parts = (v: VectorCase): { scope: SealingScope; key: SealingKey; plaintext: Buffer; stored: Buffer } => ({
  scope: { tenantId: v.tenantId, partition: v.partition },
  key: { keyId: v.keyId, key: Buffer.from(v.key, 'base64') },
  plaintext: Buffer.from(v.plaintext, 'base64'),
  stored: Buffer.from(v.stored, 'base64'),
});

const unreadable = (work: () => unknown): string => {
  try {
    work();
  } catch (error) {
    expect(error).to.be.instanceOf(ObjectUnreadableError);
    return (error as ObjectUnreadableError).reason;
  }
  return expect.fail('expected the object to be unreadable');
};

describe('SS3 workspace sealing (WS-1, WS-2)', () => {
  it('has the shared vectors', () => {
    expect(VECTORS.map((v) => v.name)).to.deep.equal(['text', 'empty', 'binary']);
  });

  for (const v of VECTORS) {
    it(`WS-1 ${v.name}: Node seals to Python's bytes, hash and object id`, async () => {
      const { scope, key, plaintext, stored } = parts(v);
      const sealed = sealObject(scope, key, plaintext);
      expect(sealed.contentHash).to.equal(v.contentHash);
      expect(sealed.sizeBytes).to.equal(v.sizeBytes);
      expect(sealed.stored.equals(stored)).to.equal(true);
      const inner = await new InMemoryWorkspaceObjects().put(v.tenantId, sealed.stored);
      expect(encodeSealedId(inner)).to.equal(v.objectId);
      expect(decodeSealedId(v.objectId)).to.deep.equal(inner);
    });

    it(`WS-1 ${v.name}: Node opens Python's bytes`, () => {
      const { scope, key, plaintext, stored } = parts(v);
      expect(openObject(scope, key, stored, v).equals(plaintext)).to.equal(true);
    });
  }

  it('WS-2: another key, tampered bytes, another partition or a wrong size are unreadable', () => {
    const { scope, key, stored } = parts(VECTORS[0]!);
    const ref = VECTORS[0]!;
    expect(unreadable(() => openObject(scope, { ...key, keyId: 'k-2' }, stored, ref))).to.equal('other_key');
    expect(unreadable(() => openObject(scope, { ...key, key: Buffer.alloc(32, 9) }, stored, ref))).to.equal('authentication');
    const tampered = Buffer.from(stored);
    tampered.writeUInt8(tampered.readUInt8(tampered.length - 1) ^ 1, tampered.length - 1);
    expect(unreadable(() => openObject(scope, key, tampered, ref))).to.equal('authentication');
    expect(unreadable(() => openObject({ ...scope, partition: 'ws:other' }, key, stored, ref))).to.equal('authentication');
    expect(unreadable(() => openObject(scope, key, stored, { ...ref, sizeBytes: ref.sizeBytes + 1 }))).to.equal('size');
    expect(unreadable(() => openObject(scope, key, Buffer.from('nope'), ref))).to.equal('malformed');
    expect(unreadable(() => decodeSealedId('sha256:abc'))).to.equal('not_sealed');
  });
});
